#!/bin/bash
# post-freeze: engine minimax / mean vs output-SQNR selection on ExDark test, lighting groups
# README 11.8 F1: same as queue_boot_exdark_sqnr.sh with the executor-corrected SQNR selections at 3 and 10% (15, 20% identical)
while ! grep -q F1BOOT_A_DONE logs/fx_boot_f1_A.out; do sleep 60; done
cd /home/thuan/isci_method_20261025
nice -n 10 /home/thuan/miniconda3/envs/qtsd/bin/python bootstrap_groups.py --gt data/exdark/exdark_test.json --sets fp32=metrics/exdark/yolo11s_fp32_test.pred.json.gz,minimax_B0.03=metrics/alloc_eval/yolo11s_int8ent/exdark_minimax_B0.03_exdark_test.pred.json.gz,sqnr_B0.03=metrics/alloc_eval/yolo11s_int8ent/fxex_sqnrq_B0.03_exdark_test.pred.json.gz,minimax_B0.1=metrics/alloc_eval/yolo11s_int8ent/exdark_minimax_B0.1_exdark_test.pred.json.gz,sqnr_B0.1=metrics/alloc_eval/yolo11s_int8ent/fxex_sqnrq_B0.1_exdark_test.pred.json.gz,minimax_B0.15=metrics/alloc_eval/yolo11s_int8ent/exdark_minimax_B0.15_exdark_test.pred.json.gz,sqnr_B0.15=metrics/alloc_eval/yolo11s_int8ent/exdark_sqnr_B0.15_exdark_test.pred.json.gz,minimax_B0.2=metrics/alloc_eval/yolo11s_int8ent/exdark_minimax_B0.2_exdark_test.pred.json.gz,sqnr_B0.2=metrics/alloc_eval/yolo11s_int8ent/exdark_sqnr_B0.2_exdark_test.pred.json.gz,mean_B0.15=metrics/alloc_eval/yolo11s_int8ent/exdark_mean_B0.15_exdark_test.pred.json.gz,mean_B0.2=metrics/alloc_eval/yolo11s_int8ent/exdark_mean_B0.2_exdark_test.pred.json.gz --ref fp32 --pairs sqnr_B0.03:minimax_B0.03,sqnr_B0.1:minimax_B0.1,sqnr_B0.15:minimax_B0.15,sqnr_B0.2:minimax_B0.2,sqnr_B0.15:mean_B0.15,sqnr_B0.2:mean_B0.2 --groups attr:light --group-names Ambient,Strong,Single,Weak,Twilight,Object,Low,Window --n 1000 --out metrics/bootstrap/g_yolo11s_exdark_sqnrfx.json
echo BOOT_EXSQNRFX_DONE
